// models/Product.js
const mongoose = require('mongoose');

const productSchema = new mongoose.Schema({
  name: { type: String, required: true, trim: true },
  price: { type: Number, required: true, min: 0 },
  tags: {
    type: [String],
    validate: {
      validator: (v) => Array.isArray(v) && v.filter((t) => t && t.trim()).length >= 3,
      message: 'A product needs at least 3 tags',
    },
  },
});
module.exports = mongoose.model('Product', productSchema);

// routes/products.js
// (separate file; mongoose is required the same way as in the model above)
const express = require('express');
const Product = require('../models/Product');
const { requireAuth, requireAdmin } = require('../middleware/auth'); // 401 / 403
const router = express.Router();

router.post('/', requireAuth, requireAdmin, async (req, res, next) => {
  try {
    const product = await Product.create(req.body);
    res.status(201).json(product);
  } catch (e) {
    if (e.name === 'ValidationError') return res.status(400).json({ message: e.message });
    next(e);
  }
});

router.delete('/:id', requireAuth, requireAdmin, async (req, res, next) => {
  try {
    const { id } = req.params;
    if (!mongoose.Types.ObjectId.isValid(id)) return res.status(400).json({ message: 'Invalid product id' });
    const deleted = await Product.findByIdAndDelete(id); // filter is { _id: ObjectId(id) }
    if (!deleted) return res.status(404).json({ message: 'Product not found' });
    res.json({ message: 'Product deleted', id });
  } catch (e) { next(e); }
});

module.exports = router;
